function receive(clientId=null){const tracking={createdCodeId:null};const blockForm=(additional=false)=>`<div class="line block-entry">${additional?`<div class="block-entry-actions"><button type="button" class="danger" data-remove-entry aria-label="Eliminar bloque adicional">${actionIcon('delete')} Eliminar bloque</button></div>`:''}${documentTypeChecklist()}<input type="hidden" name="description" value=""><label>Almacenamiento<select name="storage">${opts(s.catalogs.storage.filter(x=>x.active).map(x=>({id:x.name,name:x.name})),'Sin especificar')}</select></label>${field('Nota','notes','text','',false)}</div>`;
 form('Ingresar documento',clientPickerHTML()+'<div class="receipt-meta">'+field('Fecha de ingreso','date','date',today())+responsible()+'</div><div id="entries">'+blockForm()+'</div><button type="button" id="add-block">+ Agregar otro bloque</button>',async(f,k)=>{const blocks=[...document.querySelectorAll('.block-entry')].flatMap(el=>{const values=Object.fromEntries([...el.querySelectorAll('input[name],select[name]')].filter(input=>input.name!=='quantity').map(x=>[x.name,x.value]));return [...el.querySelector('[name=typeId]').selectedOptions].map(option=>({...values,description:values.description||name('types',option.value),typeId:option.value,quantity:[...el.querySelectorAll('[data-type-quantity]')].find(input=>input.dataset.typeQuantity===option.value)?.value||''}));});const codeId=await resolveReceiptCode(f,k,tracking);const result=await save('receive',{codeId,date:f.get('date'),responsible:f.get('responsible'),blocks},k);if(result.refreshed)notice('Registro guardado. Puedes imprimir el resumen desde la ficha o el historial.');});$('#add-block').onclick=()=>{$('#entries').insertAdjacentHTML('beforeend',blockForm(true));wireDocumentChecklists();$('#entries').lastElementChild.querySelector('[data-remove-entry]').onclick=event=>{event.currentTarget.closest('.block-entry').remove();$('#add-block').focus();};};wireDocumentChecklists();wireReceiptSearch(clientId);}
