function reopen(){const available=s.blocks.flatMap(b=>b.balances.filter(x=>['Cliente','Reciclado'].includes(x.place)).map(x=>({b,x})));if(!available.length){modal('<h2>Sin documentos para reabrir</h2><p>No hay saldos entregados al cliente o reciclados.</p>');return;}form('Reapertura explícita de documentos',field('Fecha efectiva','date','date',today())+responsible()+select('Oficina de retorno','to',['Comercial','Operativo'].map(name=>({id:name,name})))+field('Almacenamiento (solo Comercial)','storage','text','',false)+field('Motivo de reapertura','reason','text','',false)+available.map(({b,x},i)=>`<div class="line"><label><span><input type="checkbox" name="pick" value="${i}"> ${esc(code(b)?.code)} · ${esc(b.description)} · ${esc(x.place)} · ${x.quantity??'—'}</span></label>${x.quantity===null?'<p class="hint">Se reabrirá el bloque completo, con cantidad desconocida.</p>':field('Cantidad a reabrir','qty-'+i,'number',x.quantity,false)}</div>`).join(''),async(f,k)=>{const lines=f.getAll('pick').map(i=>{const {b,x}=available[Number(i)];return {blockId:b.id,from:x.place,fromStorage:x.storage,quantity:x.quantity===null?null:Number(f.get('qty-'+i)),to:f.get('to'),storage:f.get('to')==='Comercial'?f.get('storage'):''};});await save('reopen',{...Object.fromEntries(f),lines},k);});}
function printBlocks(blocks,e){let previousMargin='3';try{previousMargin=localStorage.getItem('printMargin')||'3';}catch{}const response=prompt('Margen de impresión en milímetros (0 a 10)',previousMargin);if(response===null)return;const margin=Number(response);if(!Number.isFinite(margin)||margin<0||margin>10){alert('Margen inválido');return;}try{localStorage.setItem('printMargin',String(margin));}catch{}if($('#modal').open)$('#modal').close();let style=$('#print-settings');if(!style){style=document.createElement('style');style.id='print-settings';document.head.append(style);}style.textContent='@media print{@page{size:auto;margin:'+margin+'mm}body>.print-only{width:'+(80-2*margin)+'mm}}';$('.print-only')?.remove();const el=document.createElement('div');el.className='print-only';el.innerHTML=blocks.map(b=>{
 const quantity=b.printQuantity!==undefined?b.printQuantity:((b.balances||[]).some(x=>x.quantity===null)?null:(b.balances||[]).reduce((sum,x)=>sum+x.quantity,0));
 const receipt=s.events.find(event=>!event.deleted&&event.lines.some(line=>!line.deleted&&line.blockId===b.id));
 const responsibleName=e?name('responsible',e.responsible):receipt?name('responsible',receipt.responsible):Object.hasOwn(b,'initialResponsible')?name('responsible',b.initialResponsible):b.sourceImport?.originalResponsible?.trim()||'—';
 const notes=e?.notes??b.notes;
 return `<section class="print-summary"><h2 class="print-code">${esc(code(b)?.code)}</h2><div class="print-details"><div>Fecha de ingreso: <strong>${fmt(b.date)}</strong></div><div>Archivo: <strong>${esc(name('types',b.typeId))}</strong></div>${quantity===null?'':`<div>Cantidad: <strong>${quantity}</strong></div>`}<div>Responsable: <strong>${esc(responsibleName)}</strong></div></div>${notes?`<p class="print-note"><strong>Nota:</strong> ${esc(notes)}</p>`:''}</section>`;
}).join('');document.body.append(el);try{window.print();}catch{notice('El registro sigue guardado. No se pudo abrir la impresión; puede reimprimir desde el historial.');}}
function download(mode){const q=params();if(mode==='legacy'){downloadFile(mode,q).catch(e=>notice(e.message));return;}const dates=[...s.blocks.map(b=>b.date),...s.events.map(e=>e.date)].filter(Boolean).sort();form('Descargar Excel',`<p>Selecciona un rango de fechas. Se incluyen el primer y el último día.</p><p class="hint">${mode==='history'?'El rango se aplica a la fecha efectiva de cada movimiento.':'El rango se aplica a la fecha de ingreso del archivo. Se conservan los filtros de la consulta.'}</p>`+field('Desde','exportStart','date',q.get('start')||dates[0]||today())+field('Hasta','exportEnd','date',q.get('end')||dates.at(-1)||today()),async f=>{const start=String(f.get('exportStart'));const end=String(f.get('exportEnd'));if(start>end)throw Error('La fecha inicial debe ser anterior o igual a la fecha final.');q.set('start',start);q.set('end',end);await downloadFile(mode,q);notice('Descarga de Excel preparada.');});}
