 for(const event of s.events.filter(e=>!e.deleted))event.lines.forEach((line,index)=>{const b=selected.get(line.blockId);if(!b||line.deleted)return;records.push({key:event.id+':'+index,block:b,codeId:line.codeId||b.codeId,date:event.date,at:event.at,action:event.action,place:line.to,storage:line.storage,quantity:line.quantity,notes:event.action==='Recepción'?(b.notes||event.notes):event.notes,responsible:name('responsible',event.responsible),from:line.from,initial:false,event});});
 records.sort((a,b)=>(String(a.date||'').localeCompare(String(b.date||''))||String(a.at||'').localeCompare(String(b.at||''))||a.key.localeCompare(b.key))*(q.get('order')==='asc'?1:-1));
 const latest=new Map();for(const record of records){const previous=latest.get(record.block.id);if(!previous||String(record.date||'').localeCompare(String(previous.date||''))>0||(record.date===previous.date&&String(record.at||'')>String(previous.at||'')))latest.set(record.block.id,record);}
 return records.map(record=>({...record,latest:latest.get(record.block.id)===record}));
