// Suggestions only: the user explicitly decides whether two names identify the same client.
function wireSimilarClients(input,panel,onChoose,onClear){
 const normalize=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim();
 const distance=(a,b)=>{let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){const next=[i+1];for(let j=0;j<b.length;j++)next.push(Math.min(next[j]+1,row[j+1]+1,row[j]+(a[i]===b[j]?0:1)));row=next;}return row[b.length];};
 let chosen='';
 const update=()=>{const query=normalize(input.value).slice(0,160);if(query.length<3){panel.innerHTML='';return;}
  const tokens=query.split(' ').sort().join(' ');
  const matches=s.clients.map(customer=>{const name=normalize(customer.name).slice(0,160),sorted=name.split(' ').sort().join(' ');const score=query===name?1:tokens===sorted?0.99:(name.includes(query)||query.includes(name))?0.92:1-distance(tokens,sorted)/Math.max(tokens.length,sorted.length,1);return {customer,score};}).filter(x=>x.score>=.76&&s.codes.some(c=>c.clientId===x.customer.id)).sort((a,b)=>b.score-a.score||a.customer.name.localeCompare(b.customer.name,'es')).slice(0,6);
  panel.innerHTML=matches.length?'<p class="hint"><strong>Encontramos clientes con nombres iguales o similares.</strong> Revisa sus códigos antes de crear uno nuevo.</p>'+matches.map(({customer,score})=>`<div class="similar-client"><div><strong>${esc(customer.name)}</strong><p>Códigos: ${s.codes.filter(c=>c.clientId===customer.id).map(c=>esc(c.code)).join(' · ')}</p><small>${score===1?'Nombre coincidente':'Nombre similar'}${chosen===customer.id?' · Vinculado':''}</small></div><button type="button" data-similar-client="${esc(customer.id)}" aria-pressed="${chosen===customer.id}">${chosen===customer.id?'Quitar vínculo':'Vincular con este cliente'}</button></div>`).join(''):'<p class="hint">No encontramos clientes con nombres similares. Puedes continuar con el alta.</p>';
  panel.querySelectorAll('[data-similar-client]').forEach(button=>button.onclick=()=>{const customer=s.clients.find(c=>c.id===button.dataset.similarClient);if(chosen===customer.id){chosen='';onClear();}else{chosen=customer.id;onChoose(customer);}update();});
 };
 input.addEventListener('input',()=>{chosen='';onClear();update();});return update;
}
