 const linkToggle=$('#receipt-link-toggle'),linkFields=$('#receipt-link-fields'),linkCode=$('#form [name=linkExistingCode]'),optionalLink=$('#receipt-optional-link');
 let selected=null,active=-1;
 const normalize=value=>String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es').trim();
 const close=()=>{menu.hidden=true;search.setAttribute('aria-expanded','false');search.removeAttribute('aria-activedescendant');active=-1;};
 const resetCreation=()=>{linkToggle.checked=false;linkToggle.disabled=true;linkToggle.setAttribute('aria-expanded','false');linkFields.hidden=true;linkCode.disabled=true;linkCode.required=false;linkCode.value='';optionalLink.hidden=true;box.hidden=true;$('#form [name=newSecondName]').disabled=true;$('#form [name=newSecondName]').parentElement.hidden=true;newName.disabled=true;newName.required=false;newName.parentElement.hidden=true;newCode.disabled=true;newCode.required=false;existing.value='';search.required=true;};
 const choose=code=>{selected=code;resetCreation();codeInput.value=code.id;const customer=s.clients.find(c=>c.id===code.clientId);search.value=customer.name+' · '+code.code;search.setCustomValidity('');link.hidden=false;status.textContent='Cliente seleccionado · Código del documento: '+code.code;close();};
