let disposeCatalogDrag=()=>{};
function wireCatalogOrder(){
 disposeCatalogDrag();let busy=false;
 const ids=list=>[...list.querySelectorAll('[data-order-id]')].map(row=>row.dataset.orderId);
 const commit=async(list,previous,focusId)=>{
  const order=ids(list),catalog=list.dataset.orderCatalog,expectedOrder=s.catalogs[catalog].filter(item=>!item.deleted).map(item=>item.id);
  if(JSON.stringify(order)===JSON.stringify(expectedOrder))return;
  busy=true;list.setAttribute('aria-busy','true');document.querySelectorAll('.catalog-order-list button').forEach(button=>button.disabled=true);const feedback=$('#catalog-order-feedback');if(feedback)feedback.hidden=true;
  try{
   await api('operate',{kind:'catalogReorder',key:uid(),data:{catalog,order,expectedOrder,reason:'Orden de opciones actualizado desde Administración'}});
   // Update the local state only after acknowledgement, so failed refreshes cannot revert a saved order.
   const items=s.catalogs[catalog];s.catalogs[catalog]=[...order.map(id=>items.find(item=>item.id===id)),...items.filter(item=>item.deleted)];
   const refreshed=await load();notice(refreshed?'Orden guardado. Los selectores usarán esta misma secuencia.':'Orden guardado. No se pudo actualizar la consulta; vuelve a actualizar cuando esté disponible.');document.querySelector(`[data-order-id="${focusId}"] .catalog-grip`)?.focus();
  }catch(error){
   const feedback=$('#catalog-order-feedback');if(feedback){feedback.hidden=false;const unsupported=error.message==='Operación desconocida';feedback.innerHTML='<strong>Orden pendiente de guardar</strong><p>'+esc(unsupported?'El servidor abierto usa una versión anterior y rechaza el cambio. Detén su terminal con Ctrl+C, abre Iniciar.cmd, vuelve a iniciar sesión y reintenta.':error.message)+'</p><p>El orden elegido se mantiene en esta pantalla, pero todavía no está guardado.</p><div class="toolbar"><button type="button" id="retry-catalog-order">Reintentar guardado</button><button type="button" id="reload-catalog-order">Cargar orden guardado</button></div>';$('#retry-catalog-order').onclick=()=>commit(list,previous,focusId);$('#reload-catalog-order').onclick=load;}
   notice('No se guardó el orden. Revisa el aviso en Administración.');
  }finally{busy=false;list.removeAttribute('aria-busy');document.querySelectorAll('.catalog-order-list button').forEach(button=>button.disabled=false);}
 };
 let active=null;
 const restore=()=>{if(!active)return;for(const key of active.previous){const item=active.list.querySelector(`[data-order-id="${key}"]`);if(item)active.list.append(item);}active.row.classList.remove('is-dragging');active=null;};
 const moveAt=(x,y)=>{if(!active)return;const {list,row}=active;const bounds=list.getBoundingClientRect();if(x<bounds.left-40||x>bounds.right+40)return;const next=[...list.children].find(item=>item!==row&&y<item.getBoundingClientRect().top+item.getBoundingClientRect().height/2);if(next!==row.nextElementSibling)list.insertBefore(row,next||null);};
 const finish=()=>{if(!active)return;const {list,row,previous}=active;row.classList.remove('is-dragging');active=null;commit(list,previous,row.dataset.orderId);};
 const pointerMove=e=>{if(!active||active.kind!=='touch'||e.pointerId!==active.pointerId)return;e.preventDefault();moveAt(e.clientX,e.clientY);};
 const pointerUp=e=>{if(active?.kind==='touch'&&e.pointerId===active.pointerId)finish();};
 const pointerCancel=()=>{if(active?.kind==='touch')restore();};
 const dragOver=e=>{if(!active||active.kind!=='mouse')return;const target=e.target.closest?.('[data-order-catalog]');if(target!==active.list)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';moveAt(e.clientX,e.clientY);};
 const drop=e=>{if(!active||active.kind!=='mouse')return;if(e.target.closest?.('[data-order-catalog]')!==active.list){restore();return;}e.preventDefault();finish();};
 const escape=e=>{if(e.key==='Escape'&&active){e.preventDefault();restore();}};
 document.addEventListener('pointermove',pointerMove,{passive:false});document.addEventListener('pointerup',pointerUp);document.addEventListener('pointercancel',pointerCancel);document.addEventListener('dragover',dragOver);document.addEventListener('drop',drop);document.addEventListener('keydown',escape);window.addEventListener('blur',restore);
 disposeCatalogDrag=()=>{restore();document.removeEventListener('pointermove',pointerMove);document.removeEventListener('pointerup',pointerUp);document.removeEventListener('pointercancel',pointerCancel);document.removeEventListener('dragover',dragOver);document.removeEventListener('drop',drop);document.removeEventListener('keydown',escape);window.removeEventListener('blur',restore);};
 document.querySelectorAll('.catalog-grip').forEach(handle=>{
  const row=handle.closest('[data-order-id]'),list=row.closest('[data-order-catalog]');handle.draggable=true;
  handle.onkeydown=e=>{if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key)||busy||active)return;e.preventDefault();const previous=ids(list);if(e.key==='ArrowUp'&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);else if(e.key==='ArrowDown'&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);else if(e.key==='Home')list.prepend(row);else if(e.key==='End')list.append(row);commit(list,previous,row.dataset.orderId);};
  handle.ondragstart=e=>{if(busy){e.preventDefault();return;}active={list,row,previous:ids(list),kind:'mouse'};row.classList.add('is-dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',row.dataset.orderId);}};
  handle.ondragend=()=>{if(active?.kind==='mouse')restore();};
  handle.onpointerdown=e=>{if(busy||e.button!==0||e.pointerType==='mouse'||!e.pointerType)return;e.preventDefault();handle.focus();active={list,row,previous:ids(list),kind:'touch',pointerId:e.pointerId};row.classList.add('is-dragging');};
 });
}
